#!/usr/bin/env python3
"""Reference solver by exhaustive enumeration (small instances only)."""
import itertools
from fractions import Fraction

import sys
sys.path.insert(0, '/workspace/submission')
from analyze import parse_request, Model, Invalid


def truth(inst, q):
    """Return (loads per snapshot, metrics per snapshot) using Fractions."""
    coms = inst['commodities']
    edges = inst['edges']
    snaps = inst['snapshots']
    eidx = {e['id']: i for i, e in enumerate(edges)}
    out = []
    for s in range(len(snaps)):
        qs = q[s]
        loads = [Fraction(0) for _ in edges]
        metrics = {}
        for ci, c in enumerate(coms):
            W = sum(r['weight'] for r in c['routes'])
            metrics[('demand', c['id'])] = Fraction(qs[ci])
            for r in c['routes']:
                amt = Fraction(qs[ci] * r['weight'], W)
                for eid in r['edges']:
                    loads[eidx[eid]] += amt
        for n in inst['nodes']:
            metrics[('ingress', n)] = sum((Fraction(qs[ci]) for ci, c in enumerate(coms)
                                           if c['source'] == n), Fraction(0))
            metrics[('egress', n)] = sum((Fraction(qs[ci]) for ci, c in enumerate(coms)
                                          if c['target'] == n), Fraction(0))
        for ei, e in enumerate(edges):
            metrics[('link', e['id'])] = loads[ei]
        out.append((loads, metrics))
    return out


def brute(inst):
    coms = inst['commodities']
    edges = inst['edges']
    snaps = inst['snapshots']
    C = len(coms)
    S = len(snaps)
    ranges = [range(snaps[s]['bounds'][c][0], snaps[s]['bounds'][c][1] + 1)
              for s in range(S) for c in range(C)]
    cap = [e['capacity'] for e in edges]
    feasible = []
    for combo in itertools.product(*ranges):
        q = [list(combo[s * C:(s + 1) * C]) for s in range(S)]
        info = truth(inst, q)
        ok = True
        for s in range(S):
            loads, metrics = info[s]
            for ei in range(len(edges)):
                if loads[ei] > cap[ei]:
                    ok = False
                    break
            if not ok:
                break
            for o in snaps[s]['observations']:
                if o['domain'] is None:
                    v = metrics[(o['metric'], o['target'])]
                    if not (o['lower'] <= v <= o['upper']):
                        ok = False
                        break
            if not ok:
                break
        if not ok:
            continue
        bad = set()
        for s in range(S):
            loads, metrics = info[s]
            for o in snaps[s]['observations']:
                if o['domain'] is not None:
                    v = metrics[(o['metric'], o['target'])]
                    if not (o['lower'] <= v <= o['upper']):
                        bad.add(o['domain'])
        if len(bad) <= inst['max_faults']:
            feasible.append((q, info, bad))
    if not feasible:
        return {'id': inst['id'], 'status': 'infeasible'}
    k = min(len(b) for _, _, b in feasible)
    F = [(q, info, b) for q, info, b in feasible if len(b) == k]
    forced = set(F[0][2])
    possible = set()
    for _, _, b in F:
        forced &= b
        possible |= b
    dem = []
    links = []
    verdicts = []
    status = 'unique'
    for s in range(S):
        drow = []
        for c in range(C):
            vals = [q[s][c] for q, _, _ in F]
            lo, hi = min(vals), max(vals)
            if lo != hi:
                status = 'ambiguous'
            drow.append([lo, hi])
        dem.append(drow)
        lrow = []
        for ei in range(len(edges)):
            vals = [info[s][0][ei] for _, info, _ in F]
            lo, hi = min(vals), max(vals)
            lrow.append(['%d/%d' % (lo.numerator, lo.denominator),
                         '%d/%d' % (hi.numerator, hi.denominator)])
        links.append(lrow)
        ctrl = snaps[s]['controller']
        tol = snaps[s]['tolerance']
        yes = any(all(abs(q[s][c] - ctrl[c]) <= tol for c in range(C))
                  for q, _, _ in F)
        no = any(not all(abs(q[s][c] - ctrl[c]) <= tol for c in range(C))
                 for q, _, _ in F)
        verdicts.append('undetermined' if (yes and no) else
                        ('consistent' if yes else 'inconsistent'))
    wq, winfo, wbad = F[0]
    witness = {'demands': [list(wq[s]) for s in range(S)],
               'links': [['%d/%d' % (v.numerator, v.denominator) for v in winfo[s][0]]
                         for s in range(S)],
               'faults': sorted(wbad)}
    alt = None
    if status == 'ambiguous':
        for q, info, bad in F:
            if q != wq:
                alt = {'demands': [list(q[s]) for s in range(S)],
                       'links': [['%d/%d' % (v.numerator, v.denominator) for v in info[s][0]]
                                 for s in range(S)],
                       'faults': sorted(bad)}
                break
    return {'id': inst['id'], 'status': status, 'min_faults': k,
            'faults': {'forced': sorted(forced), 'possible': sorted(possible)},
            'snapshots': [{'id': snaps[s]['id'], 'demands': dem[s], 'links': links[s],
                           'verdict': verdicts[s]} for s in range(S)],
            'witness': witness, 'alternative': alt}


def compare(expected, actual):
    """Compare all deterministic fields."""
    errs = []
    if expected['status'] != actual.get('status'):
        errs.append(('status', expected['status'], actual.get('status')))
        return errs
    if expected['status'] == 'infeasible':
        return errs
    if expected['min_faults'] != actual.get('min_faults'):
        errs.append(('min_faults', expected['min_faults'], actual.get('min_faults')))
    for key in ('forced', 'possible'):
        if sorted(expected['faults'][key]) != sorted(actual['faults'].get(key, [])):
            errs.append(('faults.' + key, expected['faults'][key],
                         actual['faults'].get(key)))
    for es, as_ in zip(expected['snapshots'], actual.get('snapshots', [])):
        if es['id'] != as_.get('id'):
            errs.append(('snap.id', es['id'], as_.get('id')))
        if es['demands'] != as_.get('demands'):
            errs.append(('demands', es['demands'], as_.get('demands')))
        if es['links'] != as_.get('links'):
            errs.append(('links', es['links'], as_.get('links')))
        if es['verdict'] != as_.get('verdict'):
            errs.append(('verdict', es['verdict'], as_.get('verdict')))
    return errs
