#!/usr/bin/env python3
"""Random incident generator for differential testing."""
import random
from fractions import Fraction


def names(prefix, n, rnd):
    return [prefix + str(i) for i in range(n)]


def gen_instance(rnd, max_nodes=4, max_edges=6, max_coms=3, max_snaps=2,
                 max_doms=3, max_bound=6, max_obs=5, max_faults=None,
                 force_faulty=False):
    N = rnd.randint(2, max_nodes)
    nodes = names('n', N, rnd)
    edges = []
    pairs = set()
    E = rnd.randint(0, max_edges)
    tries = 0
    while len(edges) < E and tries < 200:
        tries += 1
        a = rnd.choice(nodes)
        b = rnd.choice(nodes)
        if a == b:
            continue
        eid = 'e%d' % len(edges)
        edges.append({'id': eid, 'source': a, 'target': b,
                      'capacity': rnd.choice([0, 1, 3, 10, 40, 1000])})
        pairs.add((a, b))
    # commodities: random simple paths
    coms = []
    used_pairs = set()
    attempts = 0
    while len(coms) < max_coms and attempts < 200:
        attempts += 1
        a = rnd.choice(nodes)
        b = rnd.choice(nodes)
        if a == b or (a, b) in used_pairs:
            continue
        # find a random simple path a->b using random walk over edges
        path = find_path(rnd, nodes, edges, a, b)
        if path is None:
            continue
        used_pairs.add((a, b))
        nroutes = rnd.randint(1, min(3, len(path)))
        routes = []
        budget = 8
        chosen = []
        for _ in range(nroutes):
            p = path if rnd.random() < 0.5 else find_path(rnd, nodes, edges, a, b)
            if p is None:
                continue
            w = rnd.randint(1, budget)
            budget -= w
            routes.append({'edges': p, 'weight': w})
            chosen.append(p)
        if not routes:
            continue
        coms.append({'id': 'c%d' % len(coms), 'source': a, 'target': b,
                     'routes': routes})
    D = rnd.randint(0, max_doms)
    domains = names('d', D, rnd)
    mf = D if max_faults is None else min(max_faults, D)
    if rnd.random() < 0.3:
        mf = rnd.randint(0, D)
    S = rnd.randint(1, max_snaps)
    # ground truth demands
    truth = []
    for s in range(S):
        truth.append([rnd.randint(0, max_bound) for _ in coms])
    snaps = []
    for s in range(S):
        bounds = []
        for c in range(len(coms)):
            t = truth[s][c]
            lo = max(0, t - rnd.randint(0, 3))
            hi = min(10000, t + rnd.randint(0, 3))
            if rnd.random() < 0.15:
                lo, hi = 0, max_bound + 2
            bounds.append([lo, hi])
        ctrl = [max(0, min(10000, truth[s][c] + rnd.randint(-3, 3))) for c in range(len(coms))]
        tol = rnd.choice([0, 0, 1, 2, 5])
        obs = []
        targets = []
        for c in coms:
            targets.append(('demand', c['id']))
        for e in edges:
            targets.append(('link', e['id']))
        for n in nodes:
            targets.append(('ingress', n))
            targets.append(('egress', n))
        rnd.shuffle(targets)
        for i in range(min(max_obs, len(targets))):
            metric, target = targets[i]
            val = metric_value(inst_partial(nodes, edges, coms), s, metric,
                               target, truth[s])
            width = rnd.choice([0, 0, 1, 2])
            off = rnd.choice([0, 0, 0, 1, -1, 2, -2, 5, -5])
            lo = val + off
            hi = lo + width
            if rnd.random() < 0.2:
                lo, hi = lo - 3, hi + 3
            lo = max(-1000000, int(lo))
            hi = min(1000000, int(hi))
            if lo > hi:
                lo, hi = hi, lo
            dom = None
            if domains and rnd.random() < (0.75 if force_faulty else 0.5):
                dom = rnd.choice(domains)
            obs.append({'id': 'o%d' % len(obs), 'metric': metric, 'target': target,
                        'lower': lo, 'upper': hi, 'domain': dom})
        snaps.append({'id': 's%d' % s, 'bounds': bounds, 'controller': ctrl,
                      'tolerance': tol, 'observations': obs})
    return {'id': 'x', 'version': 1, 'nodes': nodes, 'edges': edges,
            'commodities': coms, 'domains': domains, 'max_faults': mf,
            'snapshots': snaps}


def inst_partial(nodes, edges, coms):
    return {'nodes': nodes, 'edges': edges, 'commodities': coms}


def find_path(rnd, nodes, edges, a, b, maxlen=4):
    adj = {}
    for e in edges:
        adj.setdefault(e['source'], []).append(e)
    for _ in range(40):
        cur = a
        seen = {a}
        path = []
        ok = True
        while cur != b:
            opts = [e for e in adj.get(cur, []) if e['target'] not in seen]
            if not opts or len(path) >= maxlen:
                ok = False
                break
            e = rnd.choice(opts)
            path.append(e['id'])
            seen.add(e['target'])
            cur = e['target']
        if ok and path:
            return path
    return None


def metric_value(inst, s, metric, target, q):
    coms = inst['commodities']
    edges = inst['edges']
    if metric == 'demand':
        for ci, c in enumerate(coms):
            if c['id'] == target:
                return Fraction(q[ci])
        return Fraction(0)
    if metric == 'link':
        tot = Fraction(0)
        for ci, c in enumerate(coms):
            W = sum(r['weight'] for r in c['routes'])
            for r in c['routes']:
                if target in r['edges']:
                    tot += Fraction(q[ci] * r['weight'], W)
        return tot
    if metric == 'ingress':
        return sum((Fraction(q[ci]) for ci, c in enumerate(coms)
                    if c['source'] == target), Fraction(0))
    return sum((Fraction(q[ci]) for ci, c in enumerate(coms)
                if c['target'] == target), Fraction(0))
